kpi_avg = latest_pd["open_defecation_pct"].mean()

kpi_max = latest_pd.loc[
    latest_pd["open_defecation_pct"].idxmax()
]

filtered_min = latest_pd[
    latest_pd["open_defecation_pct"] &gt;= 0.15
].copy()

kpi_min = filtered_min.loc[
    filtered_min["open_defecation_pct"].idxmin()
]

kpi_critical = (latest_pd["open_defecation_pct"] &gt; 50).sum()




